function readStudy(){try{const v=JSON.parse(localStorage.getItem(studyKey)||'{}');return{current:Number.isInteger(v.current)&&v.current>=0&&v.current<stages.length?v.current:0,completed:Array.isArray(v.completed)?v.completed.filter(n=>Number.isInteger(n)&&n>=0&&n<stages.length):[]};}catch{return{current:0,completed:[]};}}
let studyState=readStudy();
function persistStudy(){try{localStorage.setItem(studyKey,JSON.stringify(studyState));}catch{}}
function refreshStudyStatus(){const box=el('studyResume');if(!box)return;const count=studyState.completed.length;box.hidden=count===0&&studyState.current===0;el('studyProgressText').textContent=count+' de '+stages.length+' estaciones revisadas \u00b7 \u00faltima visita: '+stages[studyState.current][0];el('resumeStudy').dataset.openStep=String(studyState.current);el('resumeStudy').textContent='Retomar estaci\u00f3n '+String(studyState.current+1).padStart(2,'0');}
function stage(n){current=(n+stages.length)%stages.length;studyState.current=current;persistStudy();let a=stages[current],g=stationGuide[current];el('stepCount').textContent=String(current+1).padStart(2,'0');el('stepRail').innerHTML=stages.map((s,i)=>'<button type="button" class="'+(i===current?'active':'')+'" data-step="'+i+'"><span>'+String(i+1).padStart(2,'0')+'</span>'+escape(s[0])+'</button>').join('');el('stepDetail').innerHTML='<div class="eyebrow">'+escape(a[1])+' / ESTACIÓN '+String(current+1).padStart(2,'0')+'</div><h3>'+escape(a[2])+'</h3><p class="summary">'+escape(a[3])+'</p><div class="facts"><div class="fact"><small>Quién actúa</small><strong>'+escape(a[4])+'</strong></div><div class="fact"><small>Plazo</small><strong>'+escape(a[5])+'</strong></div><div class="fact"><small>Fundamento</small><strong>'+escape(a[6])+'</strong></div></div><div class="station-next"><div><small>Documento o resultado</small><p>'+escape(g[0])+'</p></div><div><small>Qué viene después</small><p>'+escape(g[1])+'</p></div></div><div class="example"><strong>Aplicación a Arcadia</strong>'+escape(a[7])+'</div><div class="nuance"><strong>No confundas</strong>'+escape(a[8])+'</div>';const check=stageChecks[current];el('stepDetail').insertAdjacentHTML('beforeend','<fieldset class="stage-challenge"><legend>Comprueba tu comprensi&oacute;n</legend><p>'+escape(check.prompt)+'</p><div class="stage-challenge-options">'+check.options.map((option,index)=>'<button type="button" data-stage-answer="'+index+'" aria-pressed="false">'+escape(option)+'</button>').join('')+'</div><div class="stage-hint-row"><button class="stage-hint-button" type="button" data-stage-hint aria-expanded="false">Ver una pista</button><p class="stage-hint" data-stage-hint-text aria-live="polite" hidden></p></div><p class="stage-check-feedback" aria-live="polite">Elige una respuesta para ver por qu&eacute;.</p></fieldset>');let hintLevel=0;const hintButton=el('stepDetail').querySelector('[data-stage-hint]'),hintText=el('stepDetail').querySelector('[data-stage-hint-text]');hintButton.addEventListener('click',()=>{if(hintLevel>=check.hints.length){hintLevel=0;hintText.hidden=true;hintButton.setAttribute('aria-expanded','false');hintButton.textContent='Ver una pista';return;}hintText.textContent=check.hints[hintLevel++];hintText.hidden=false;hintButton.setAttribute('aria-expanded','true');hintButton.textContent=hintLevel<check.hints.length?'Ver otra pista':'Ocultar pistas';});el('stepDetail').querySelectorAll('[data-stage-answer]').forEach(button=>button.addEventListener('click',()=>{const correct=Number(button.dataset.stageAnswer)===check.answer;el('stepDetail').querySelectorAll('[data-stage-answer]').forEach(choice=>{choice.setAttribute('aria-pressed',String(choice===button));choice.classList.remove('is-correct','is-wrong');});button.classList.add(correct?'is-correct':'is-wrong');const feedback=el('stepDetail').querySelector('.stage-check-feedback');feedback.className='stage-check-feedback '+(correct?'is-correct':'is-wrong');feedback.textContent=(correct?'Correcto. ':'Vuelve a mirar la pregunta. ')+check.why;}));const studied=studyState.completed.includes(current);el('stepDetail').insertAdjacentHTML('beforeend','<div class="study-mark"><label><input id="stageStudied" type="checkbox" '+(studied?'checked':'')+'><span>Marcar esta estaci\u00f3n como estudiada</span></label><small>El avance se guarda solo en este dispositivo.</small></div>');el('stageStudied').addEventListener('change',e=>{studyState.completed=e.target.checked?[...new Set([...studyState.completed,current])]:studyState.completed.filter(n=>n!==current);persistStudy();refreshStudyStatus();});refreshStudyStatus();el('stepProgress').innerHTML=stages.map((_,i)=>'<i class="'+(i<=current?'active':'')+'"></i>').join('');document.querySelectorAll('[data-step]').forEach(b=>b.addEventListener('click',()=>stage(Number(b.dataset.step))));}
el('resumeStudy').addEventListener('click',e=>{e.preventDefault();stage(Number(e.currentTarget.dataset.openStep)||0);});el('resetStudy').addEventListener('click',()=>{studyState={current:0,completed:[]};persistStudy();stage(0);});
el('prevStep').addEventListener('click',()=>stage(current-1));el('nextStep').addEventListener('click',()=>stage(current+1));stage(studyState.current);
