function addMonths(d,n){let x=new Date(d.getTime()),day=x.getUTCDate();x.setUTCDate(1);x.setUTCMonth(x.getUTCMonth()+n);let m=x.getUTCMonth();x.setUTCMonth(m+1);x.setUTCDate(0);let last=x.getUTCDate();x.setUTCDate(Math.min(day,last));return x;}
function calc(){let x=deadlines[Number(el('clockRule').value)||0],v=el('clockStart').value;if(!/^\d{4}-\d{2}-\d{2}$/.test(v)){el('clockDate').textContent='Selecciona una fecha';return;}let d=new Date(v+'T12:00:00Z');if(!Number.isFinite(d.getTime()))return;let out=x[2]==='meses'?addMonths(d,x[1]):new Date(d.getTime()+x[1]*86400000);el('clockDate').textContent=new Intl.DateTimeFormat('es-ES',{dateStyle:'long',timeZone:'UTC'}).format(out);el('clockTitle').textContent=x[0];el('clockExplanation').textContent='Acto inicial: '+x[3]+'. '+x[5];el('clockAuthority').textContent=x[4]+' · Fecha ORIENTATIVA, no vencimiento jurídico certificado.';}
el('clockGo').addEventListener('click',calc);el('clockRule').addEventListener('change',calc);calc();
const caseStations=[4,0,2,5,7,8,9,11];let caseIndex=0;function viewCase(n){caseIndex=n;let a=caseFacts[n];el('caseList').innerHTML=caseFacts.map((x,i)=>'<button type="button" data-case="'+i+'" class="'+(i===n?'active':'')+'"><span>'+escape(x[0])+'</span><strong>'+escape(x[1])+'</strong></button>').join('');el('caseDetail').innerHTML='<div class="eyebrow">EXPEDIENTE / '+escape(a[0])+'</div><h3>'+escape(a[1])+'</h3><p>'+escape(a[2])+'</p><div class="question"><strong>Pregunta para comprender</strong><p>'+escape(a[3])+'</p></div>';el('caseDetail').insertAdjacentHTML('beforeend','<a class="case-stage-link" href="#recorrido" data-open-step="'+caseStations[n]+'">Repasar estaci\u00f3n relacionada</a>');el('caseDetail').querySelector('[data-open-step]').addEventListener('click',e=>stage(Number(e.currentTarget.dataset.openStep)));document.querySelectorAll('[data-case]').forEach(b=>b.addEventListener('click',()=>viewCase(Number(b.dataset.case))));}viewCase(0);
const caseSim={path:null,index:0,answered:false,decisions:{}};
function drawCaseTrail(){const trail=el('caseSimTrail');if(!caseSim.path){trail.hidden=true;trail.innerHTML='';return;}const path=caseScenarioPaths[caseSim.path];trail.hidden=false;trail.innerHTML='<p>Tu recorrido <span>Elige una decisi&oacute;n anterior para revisar su explicaci&oacute;n.</span></p><ol>'+path.map((id,index)=>{const answer=caseSim.decisions[id],state=answer===undefined?'pending':answer.correct?'correct':'wrong';return '<li><button type="button" data-trail-step="'+index+'" class="'+state+(index===caseSim.index?' current':'')+'" '+(answer===undefined&&index!==caseSim.index?'disabled':'')+' aria-current="'+(index===caseSim.index?'step':'false')+'"><span>'+(answer===undefined?'·':answer.correct?'✓':'!')+'</span>'+escape(caseScenarioNodes[id].title)+'</button></li>';}).join('')+'</ol>';trail.querySelectorAll('[data-trail-step]:not(:disabled)').forEach(button=>button.addEventListener('click',()=>{caseSim.index=Number(button.dataset.trailStep);renderCaseSim();}));}
function resetCaseSim(){caseSim.path=null;caseSim.index=0;caseSim.answered=false;caseSim.decisions={};el('caseSimProgressText').textContent='Elige una ruta para comenzar';el('caseSimProgressBar').style.width='0%';el('caseSimCard').innerHTML='<div class="case-sim-start"><h4>¿Dónde empieza tu análisis?</h4><p>Elige si quieres recorrer primero la petición ante la Comisión o practicar desde el momento en que el caso llega a la Corte.</p><div class="case-sim-route-buttons"><button type="button" data-sim-path="cidh">Empezar desde la CIDH <span>19 decisiones · petición a cumplimiento</span></button><button type="button" data-sim-path="court">Empezar en la Corte <span>10 decisiones · sometimiento a cumplimiento</span></button></div></div>';el('caseSimRetry').hidden=true;el('caseSimStageLink').hidden=true;el('caseSimNext').hidden=true;el('caseSimNext').disabled=true;drawCaseTrail();el('caseSimCard').querySelectorAll('[data-sim-path]').forEach(b=>b.addEventListener('click',()=>{caseSim.path=b.dataset.simPath;caseSim.index=0;renderCaseSim();}));}
function renderCaseSim(){const path=caseScenarioPaths[caseSim.path],node=caseScenarioNodes[path[caseSim.index]],saved=caseSim.decisions[path[caseSim.index]];caseSim.answered=Boolean(saved);el('caseSimProgressText').textContent=(caseSim.path==='cidh'?'Ruta CIDH':'Ruta Corte')+' · decisión '+(caseSim.index+1)+' de '+path.length+' · '+Object.keys(caseSim.decisions).length+' respondidas';el('caseSimProgressBar').style.width=(100*Object.keys(caseSim.decisions).length/path.length)+'%';drawCaseTrail();el('caseSimCard').innerHTML='<div class="case-sim-heading"><span>'+escape(node.phase)+'</span><h4>'+escape(node.title)+'</h4></div><p class="case-sim-context">'+escape(node.context)+'</p><fieldset class="case-sim-question"><legend>'+escape(node.prompt)+'</legend><div class="case-sim-options">'+node.options.map((option,index)=>'<button type="button" data-sim-answer="'+index+'" '+(saved?'disabled':'')+'>'+escape(option.text)+'</button>').join('')+'</div></fieldset><div class="case-sim-feedback" aria-live="polite" '+(saved?'':'hidden')+'></div><div class="case-sim-links"><a href="'+escape(node.source)+'" target="_blank" rel="noopener noreferrer">Fuente: '+escape(node.sourceLabel)+' ↗</a><a href="#recorrido" data-open-step="'+node.stage+'">Repasar estación: '+escape(stages[node.stage][0])+' →</a></div>';el('caseSimRetry').hidden=!saved;el('caseSimStageLink').hidden=!saved;el('caseSimNext').hidden=!saved;el('caseSimNext').disabled=!saved;const feedback=el('caseSimCard').querySelector('.case-sim-feedback');if(saved){el('caseSimCard').querySelectorAll('[data-sim-answer]').forEach((choice,index)=>choice.classList.add(node.options[index].correct?'is-correct':index===saved.picked?'is-wrong':'is-neutral'));feedback.classList.add(saved.correct?'is-correct':'is-wrong');feedback.innerHTML='<strong>'+(saved.correct?'Bien razonado.':'Revisa esta decisión.')+'</strong><p>'+escape(node.options[saved.picked].feedback)+'</p>';}el('caseSimCard').querySelectorAll('[data-sim-answer]:not(:disabled)').forEach(button=>button.addEventListener('click',()=>{if(caseSim.answered)return;caseSim.answered=true;const picked=Number(button.dataset.simAnswer),correct=node.options[picked].correct;caseSim.decisions[path[caseSim.index]]={picked,correct};el('caseSimCard').querySelectorAll('[data-sim-answer]').forEach((choice,index)=>{choice.disabled=true;choice.classList.add(node.options[index].correct?'is-correct':index===picked?'is-wrong':'is-neutral');});feedback.hidden=false;feedback.classList.add(correct?'is-correct':'is-wrong');feedback.innerHTML='<strong>'+(correct?'Bien razonado.':'Revisa esta decisión.')+'</strong><p>'+escape(node.options[picked].feedback)+'</p>';el('caseSimStageLink').hidden=false;el('caseSimNext').hidden=false;el('caseSimNext').disabled=false;el('caseSimRetry').hidden=false;drawCaseTrail();}));el('caseSimCard').querySelector('[data-open-step]').addEventListener('click',e=>stage(Number(e.currentTarget.dataset.openStep)));}
