async function initOasMap(){const canvas=el('oasMapCanvas');if(!canvas)return;try{const response=await fetch('assets/mapa-americas.svg');if(!response.ok)throw new Error('Map request failed');canvas.innerHTML=await response.text();const svg=canvas.querySelector('svg');svg?.querySelectorAll('[data-code]').forEach(shape=>{const state=stateByCode.get(shape.dataset.code);shape.setAttribute('aria-label',(state?.name||shape.dataset.name)+(state?.status==='member'?' · Estado miembro de la OEA':state?.status==='former'?' · retiro efectivo en 2023':' · no es Estado miembro actual'));shape.addEventListener('click',()=>selectMapCountry(shape.dataset.code));shape.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();selectMapCountry(shape.dataset.code);}});});renderMemberList();setMapView(0,0,1000);el('mapZoomIn').addEventListener('click',()=>zoomMapBy(.72));el('mapZoomOut').addEventListener('click',()=>zoomMapBy(1.39));el('mapZoomReset').addEventListener('click',()=>setMapView(0,0,1000));el('mapSearch').addEventListener('input',event=>{const query=event.target.value;renderMemberList(query);renderMapSearchResults(query,svg);const q=normalizeSearch(query),match=q.length<2?null:[...canvas.querySelectorAll('[data-code]')].find(shape=>normalizeSearch((stateByCode.get(shape.dataset.code)?.name||shape.dataset.name||'')).includes(q));canvas.querySelectorAll('[data-code]').forEach(shape=>shape.classList.toggle('is-match',Boolean(match)&&shape.dataset.code===match.dataset.code));});}catch{canvas.innerHTML='<p class="map-loading">No se pudo cargar el mapa. Puedes consultar los 34 Estados miembros en la lista de abajo.</p>';renderMemberList();}}
